const icon=(n)=>`<svg class="icon" aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[n]||paths.ball}"/></svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function render(){const names=Object.fromEntries([...navItems,['studio','','Design Studio'],['discord','','Discord Hub'],['profile','','O meu perfil'],['admin','','Administração'],['competition','','Competições'],['setup','','Configuração'],['login','','Entrar']].map(x=>[x[0],x[2]]));document.getElementById('app').innerHTML=`<aside class="sidebar"><a href="#home" class="brand" aria-label="MES início"><span class="brand-mark">M</span><div class="brand-name">MES<small>EUROPEAN SERIES</small></div></a><div class="nav-label">A TUA LIGA</div>${navItems.map(([p,i,t])=>`<button class="nav ${page===p||(p==='competitions'&&page==='competition')?'active':''}" data-nav="${p}">${icon(i)}${t}${p==='competitions'?`<span class="count">${state.competitions.length}</span>`:''}</button>`).join('')}<div class="nav-label">COMUNIDADE</div>${[['studio','studio','Design Studio'],['profile','player','O meu perfil'],['admin','settings','Administração'],['setup','link','Configuração']].filter(([p])=>!['admin','setup'].includes(p)||state.permissions.admin).map(([p,i,t])=>`<button class="nav ${page===p?'active':''}" data-nav="${p}">${icon(i)}${t}${p==='admin'&&state.requests.some(r=>r.status==='Pendente')?`<span class="count">${state.requests.filter(r=>r.status==='Pendente').length}</span>`:''}</button>`).join('')}<div class="sidebar-bottom"><div class="discord-mini"><div style="display:flex;align-items:center;gap:8px;color:#c5bbf2;font-size:12px">${icon('discord')}A liga vive no Discord</div><p>O teu perfil. A tua equipa.<br>A tua próxima competição.</p><button data-nav="discord">Discord · próxima fase ↗</button></div><div class="sidebar-foot"><span class="dot"></span>THE FUTURE OF MAMOBALL</div></div></aside><div class="shell"><header class="topbar"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Abrir menu">${icon('menu')}</button><div class="breadcrumb"><span>MES</span><span>/</span><strong>${names[page]||'Visão geral'}</strong></div><div class="top-actions"><form class="searchbox" id="global-search">${icon('search')}<input name="query" placeholder="Pesquisar na liga..." aria-label="Pesquisar na liga" required><span class="key">↵</span></form><button class="icon-btn" data-action="activity" aria-label="Atividade">${icon('bell')}</button>${!state.permissions.authenticated?`<button class="btn purple small" data-nav="login">${icon('discord')}Entrar</button>`:''}<button class="avatar" data-nav="profile" aria-label="O meu perfil">${avatarHtml(state.profile?.avatar,state.profile?.nick?state.profile.nick.slice(0,2).toUpperCase():'TU')}</button></div></header><main class="main">${state.config.storageReady===false?'<div class="notice">MES em preparação · Navegação disponível. O login e os registos serão ativados pela organização.</div>':''}${view()}<footer class="bottom-line"><span>© 2026 MAMOBALL EUROPEAN SERIES <span style="margin-left:12px">The Future of Mamoball</span></span><span>Base de dados partilhada · Horário de Lisboa</span></footer></main></div>`;if(page==='studio')drawStudio();}
function heading(eyebrow,title,desc,action=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`}
const pitch=`<svg viewBox="0 0 460 280" aria-hidden="true"><defs><linearGradient id="pitch" x2="0" y2="1"><stop stop-color="#688448"/><stop offset="1" stop-color="#293c23"/></linearGradient><linearGradient id="rim"><stop stop-color="#d7ffa0"/><stop offset="1" stop-color="#6b8c42"/></linearGradient></defs><path d="M40 75 309 27 429 190 151 248Z" fill="#0b1209" stroke="#34472a" stroke-width="3"/><path d="m40 64 269-48 120 163-278 58Z" fill="url(#pitch)" stroke="url(#rim)" stroke-width="1.5"/><path d="m54 70 249-44 111 146-257 54Z" fill="none" stroke="#b9d991" stroke-opacity=".6"/><path d="m177 48 114 150" fill="none" stroke="#b9d991" stroke-opacity=".6"/><ellipse cx="232" cy="124" rx="40" ry="28" transform="rotate(25 232 124)" fill="none" stroke="#b9d991" stroke-opacity=".6"/><path d="m75 98 52-10 48 61-54 11m224-79-48 10 49 64 49-11" fill="none" stroke="#b9d991" stroke-opacity=".6"/><path d="m90 123-18 4 20 26 17-4m255-43 18-4 20 27-18 4" fill="none" stroke="#efffd6"/><g fill="#d4ff95" stroke="#17270e" stroke-width="3"><ellipse cx="171" cy="97" rx="10" ry="7"/><ellipse cx="233" cy="156" rx="10" ry="7"/><ellipse cx="135" cy="136" rx="10" ry="7"/></g><g fill="#bd9af7" stroke="#302047" stroke-width="3"><ellipse cx="291" cy="102" rx="10" ry="7"/><ellipse cx="327" cy="145" rx="10" ry="7"/><ellipse cx="272" cy="181" rx="10" ry="7"/></g><circle cx="239" cy="114" r="9" fill="#eef5e7" stroke="#273225" stroke-width="2"/><path d="m237 110 5 2-1 5h-5l-1-4Z" fill="#526047"/><path d="m310 52 4-17m-9 9 16-1M113 202l-2 10m-5-4 13-2" stroke="#c2f970" stroke-width="2"/></svg>`;
function teamCard(t){return `<button class="panel team-card" data-team="${t.id}" style="text-align:left"><div class="card-top">${shield(t,true)}${badge(t.region,'gray')}</div><h3>${esc(t.name)}</h3><div class="muted small">${esc(t.tag)}</div><div class="team-bottom"><span>Capitão <b>${esc(t.captain)}</b></span><span>${t.members} jogadores</span></div></button>`}
function teamsView(){return `${heading('CONSTRÓI O TEU LEGADO','AS EQUIPAS','Equipas oficiais. Registos e inscrições geridos pela administração.',(state.permissions.admin?btn('Registar equipa','register-team','primary','plus'):''))}<div class="filters"><input class="search-field" id="team-search" placeholder="Procurar equipa..." aria-label="Procurar equipa" value="${esc(teamQuery)}"></div><div class="grid3" id="team-results">${teamResults()}</div>`}
function teamResults(){const ts=state.teams.filter(t=>t.name.toLowerCase().includes(teamQuery.toLowerCase()));return ts.map(teamCard).join('')||'<p class="muted">Nenhuma equipa encontrada.</p>'}
let state={teams:[],players:[],competitions:[],entries:[],matches:[],requests:[],events:[],awards:[],tables:{},permissions:{},config:{},profile:null,studio:{type:'Resultado',home:null,away:null,score:'0 : 0',accent:'#c2f970'}};
let page=(typeof window.location!=='undefined'&&['home','profile','login','setup','about','newcomers'].includes(window.location.hash.slice(1)))?window.location.hash.slice(1):'home',filter='Todas',detailTab='',calendarFilter='Todos',playerQuery='',teamQuery='',compId=null,busy=false;
const navItems=[['home','home','Visão geral'],['competitions','trophy','Competições'],['calendar','calendar','Calendário'],['teams','teams','Equipas'],['players','player','Jogadores'],['hall','star','Hall of Fame'],['about','shield','Sobre a MES'],['newcomers','player','Começa aqui']];
const team=id=>state.teams.find(t=>t.id===Number(id));
const avatarHtml=(url,label)=>url?`<img src="${esc(url)}" alt="" loading="lazy" referrerpolicy="no-referrer">`:esc(label);
const bannerAttrs=b=>b?.url?`class="profile-cover has-image" style="background-image:url('${esc(b.url)}')"`:`class="profile-cover banner-${esc(b?.preset||'lime')}"`;
const BANNER_NAMES={lime:'Lima',pitch:'Relvado',violet:'Violeta',ember:'Brasa',ocean:'Oceano',night:'Noite'};
function waitLeft(iso){const ms=Date.parse(iso||'')-Date.now();if(!(ms>0))return '';const t=Math.ceil(ms/60000),h=Math.floor(t/60),m=t%60;return h?`${h}h ${m}min`:`${m}min`}
const ticketButton=()=>state.config.ticketUrl?`<a class="btn ghost" href="${esc(state.config.ticketUrl)}" target="_blank" rel="noopener noreferrer">${icon('discord')}Abrir ticket no Discord</a>`:`<button class="btn ghost" type="button" disabled title="O servidor Discord da MES ainda não está configurado.">${icon('discord')}Abrir ticket no Discord</button>`;
function mamoPanel(p){const pending=(p.idRequests||[]).find(r=>r.status==='Pendente'),wait=waitLeft(p.nextIdChange),history=(p.idRequests||[]).filter(r=>r.status!=='Pendente').slice(0,3);
 if(!p.mamo)return `<div class="panel section-pad lower"><div class="section-head"><h3 style="margin:0">ID Mamoball</h3>${badge('Por definir','orange')}</div><form id="mamo-form"><div class="field"><label for="f-mamo">O teu ID Mamoball</label><input id="f-mamo" name="mamo" required minlength="6" maxlength="6" pattern="[A-Za-z0-9]{6}" autocomplete="off" spellcheck="false" placeholder="Ex.: A1B2C3" class="mono-input"></div><p class="muted small" style="line-height:1.8;margin-bottom:18px">6 caracteres, letras e números. Depois de guardado, só podes alterar o ID através de um pedido à administração.</p><div class="row-actions"><button class="btn primary" type="submit">${icon('check')}Guardar ID</button>${ticketButton()}</div></form></div>`;
 return `<div class="panel section-pad lower"><div class="section-head"><h3 style="margin:0">ID Mamoball</h3>${pending?badge('Alteração pendente','orange'):badge('Definido')}</div><div class="mamo-id">${esc(p.mamo)}</div>${pending?`<p class="muted small" style="line-height:1.8;margin:14px 0 18px">Pedido de alteração para <b class="mono">${esc(pending.new_mamo)}</b> em análise pela administração.</p>`:wait?`<p class="muted small" style="line-height:1.8;margin:14px 0 18px">Podes pedir uma nova alteração dentro de <b>${wait}</b>.</p>`:`<p class="muted small" style="line-height:1.8;margin:14px 0 18px">Para mudar de ID, envia um pedido. A administração confirma a alteração. Só podes fazer um pedido a cada 24 horas.</p>`}<div class="row-actions">${pending||wait?`<button class="btn" type="button" disabled>${icon('clock')}Pedir alteração de ID</button>`:btn('Pedir alteração de ID','id-change','','edit')}${ticketButton()}</div>${history.map(r=>`<div class="list-item"><span class="small mono">${esc(r.old_mamo)} → ${esc(r.new_mamo)}</span>${badge(r.status,r.status==='Aprovado'?'':'gray')}</div>`).join('')}</div>`}
async function prepareImage(file,kind){if(!file||!/^image\//.test(file.type))throw new Error('Escolhe uma imagem PNG, JPG ou WEBP.');if(file.size>15e6)throw new Error('Imagem demasiado grande.');const bmp=await createImageBitmap(file);const [w,h]=kind==='avatar'?[256,256]:[1500,500];const c=document.createElement('canvas');c.width=w;c.height=h;const g=c.getContext('2d');const scale=Math.max(w/bmp.width,h/bmp.height),sw=w/scale,sh=h/scale;g.drawImage(bmp,(bmp.width-sw)/2,(bmp.height-sh)/2,sw,sh,0,0,w,h);const max=kind==='avatar'?190000:580000;for(const q of [0.86,0.75,0.62,0.5]){let url=c.toDataURL('image/webp',q);if(!url.startsWith('data:image/webp'))url=c.toDataURL('image/jpeg',q);if(url.length*0.75<max)return url}throw new Error('Imagem demasiado grande.')}
function customizeModal(){const p=state.profile,raw=p.style||{},st={...raw,avatar:raw.avatar==='discord'&&!p.hasDiscordAvatar?'initials':raw.avatar,banner:raw.banner==='discord'&&!p.hasDiscordBanner?'preset':raw.banner},opt=(name,value,label,on,disabled=false)=>`<label class="choice ${disabled?'disabled':''}"><input type="radio" name="${name}" value="${value}" ${on?'checked':''} ${disabled?'disabled':''}><span>${label}</span></label>`;
 modal('Personalizar perfil',`<form id="style-form"><div class="custom-preview"><div ${bannerAttrs(p.banner)}></div><div class="profile-avatar">${avatarHtml(p.avatar,(p.nick||'TU').slice(0,2).toUpperCase())}</div></div>
 <h3 class="custom-title">Imagem de perfil</h3><div class="choice-row">${opt('avatar','discord','Discord',st.avatar==='discord',!p.hasDiscordAvatar)}${opt('avatar','upload','Imagem carregada',st.avatar==='upload',!(st.avatar==='upload'))}${opt('avatar','initials','Iniciais',st.avatar==='initials')}</div>
 <div class="upload-row"><label class="btn small">${icon('plus')}Carregar imagem<input type="file" accept="image/png,image/jpeg,image/webp" data-upload="avatar" hidden></label>${st.avatar==='upload'?btn('Remover','media-remove:avatar','small ghost'):''}<span class="muted small">Quadrada, mín. 256 × 256 px.</span></div>
 <h3 class="custom-title">Banner</h3><div class="swatches">${['lime','pitch','violet','ember','ocean','night'].map(k=>`<label class="swatch banner-${k}" title="${BANNER_NAMES[k]}"><input type="radio" name="preset" value="${k}" ${st.preset===k?'checked':''}><span class="sr-only">${BANNER_NAMES[k]}</span></label>`).join('')}</div>
 <div class="choice-row">${opt('banner','preset','Cor da MES',st.banner==='preset')}${opt('banner','discord','Banner do Discord',st.banner==='discord',!p.hasDiscordBanner)}${opt('banner','upload','Imagem carregada',st.banner==='upload',!(st.banner==='upload'))}</div>
 <div class="upload-row"><label class="btn small">${icon('plus')}Carregar banner<input type="file" accept="image/png,image/jpeg,image/webp" data-upload="banner" hidden></label>${st.banner==='upload'?btn('Remover','media-remove:banner','small ghost'):''}<span class="muted small">Recomendado 1500 × 500 px.</span></div>
 <p class="muted small" style="line-height:1.7;margin:16px 0">As imagens são públicas. Conteúdo ofensivo pode ser removido pela administração.</p><button class="btn primary" type="submit">${icon('check')}Guardar</button></form>`)}
document.addEventListener('change',async e=>{const input=e.target;if(input?.dataset?.upload){const kind=input.dataset.upload;try{toast('A preparar a imagem…');const image=await prepareImage(input.files[0],kind);await mutate('media.upload',{kind,image},'profile')}catch(err){toast(err.message)}return}if(input?.name==='preset'&&input.closest('#style-form')){const b=document.querySelector('#style-form input[name=banner][value=preset]');if(b)b.checked=true;const cover=document.querySelector('.custom-preview .profile-cover');if(cover){cover.className='profile-cover banner-'+input.value;cover.style.backgroundImage=''}}});
const badge=(text,cls='')=>`<span class="badge ${cls}">${esc(text)}</span>`;
const shield=(t,large=false)=>t?`<span class="shield ${large?'large':''}" style="--team:${/^#[0-9a-f]{6}$/i.test(t.color)?t.color:'#c2f970'}">${esc(t.tag.slice(0,3))}</span>`:'';
const btn=(text,action,cls='',ic='')=>`<button class="btn ${cls}" data-action="${action}">${ic?icon(ic):''}${text}</button>`;
const empty=(title,desc,ic='trophy')=>`<div class="panel empty">${icon(ic)}<h3>${title}</h3><p>${desc}</p></div>`;
const field=(label,name,value='',max=60)=>`<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" value="${esc(value)}" required maxlength="${max}"></div>`;
function toast(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),4500)}
function nav(p){if(['admin','setup'].includes(p)&&!state.permissions.admin){toast('Área reservada à administração.');return}page=p;filter='Todas';detailTab='';if(window.history)window.history.replaceState(null,'','#'+p);render();window.scrollTo(0,0)}
async function api(op,data){const res=await fetch(op==='state'?'/api/state':'/api/action',op==='state'?{cache:'no-store'}:{method:'POST',headers:{'Content-Type':'application/json','X-Nexus-Request':'1'},body:JSON.stringify({op,data})});let result;try{result=await res.json()}catch{throw new Error('Não foi possível contactar a liga. Atualiza a página.')}if(!res.ok){const e=new Error(result.error||'Pedido não concluído.');e.authError=result.authError;throw e}return result}
async function refresh(){const studio=state.studio;state={...await api('state'),studio};if(!team(studio.home))studio.home=state.teams[0]?.id;if(!team(studio.away))studio.away=state.teams[1]?.id||state.teams[0]?.id;render()}
async function mutate(op,data,next){if(busy)return;busy=true;document.querySelectorAll('.modal button[type=submit],#profile-form button').forEach(b=>b.disabled=true);try{const r=await api(op,data);closeModal();if(next)page=next;await refresh();toast(r.message||'Guardado.');return r}catch(e){if(e.authError&&e.authError!=='discord_unavailable'){authNotice=e.authError;state.permissions={admin:false,owner:false,authenticated:false,member:false};closeModal();page='login';render()}toast(e.message)}finally{busy=false;document.querySelectorAll('.modal button[type=submit],#profile-form button').forEach(b=>b.disabled=false)}}
function view(){return ({home:homeView,about:aboutView,newcomers:newcomerView,competitions:competitionsView,calendar:calendarView,teams:teamsView,players:playersView,hall:hallView,studio:studioView,discord:discordView,profile:profileView,admin:adminView,competition:competitionView,setup:setupView,login:loginView}[page]||homeView)()}
function compRow(c){return `<button class="comp-row" style="text-align:left;width:100%" data-comp="${c.id}"><span class="competition-symbol ${c.color}">${icon('trophy')}</span><span class="comp-info"><h3>${esc(c.name)}</h3><span class="meta">${esc(c.mode)} · ${esc(c.format)} · ${state.entries.filter(e=>e.competition_id===c.id).length}/${c.teams} equipas</span></span>${badge(c.status,c.color)}${icon('chevron')}</button>`}
function matchCard(m,editable=false){const a=team(m.home_id),b=team(m.away_id),c=state.competitions.find(c=>c.id===m.competition_id);return `<div class="match"><div class="match-meta"><span>${esc(c?.name||'')} · R${m.round}${m.group_name?' · Grupo '+esc(m.group_name):''}</span><span>${m.scheduled?new Date(m.scheduled).toLocaleString((window.MES_LOCALE||'pt-PT'),{timeZone:'Europe/Lisbon',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}):'Data por definir'}</span></div><div class="match-teams"><div class="match-team">${shield(a)}<span>${esc(a?.name)}</span></div><span class="score">${m.home_score===null?'VS':m.home_score+' : '+m.away_score}</span><div class="match-team"><span>${esc(b?.name)}</span>${shield(b)}</div></div>${m.winner_id&&m.home_score===m.away_score?`<p class="small muted" style="margin-top:10px">Desempate: ${esc(team(m.winner_id)?.name)}</p>`:''}${editable&&c?.rawStatus==='active'?`<button class="link lime" data-match="${m.id}" style="margin-top:13px">Editar horário / resultado →</button>`:''}</div>`}
function homeView(){const upcoming=state.matches.filter(m=>m.home_score===null).slice(0,3),first=state.competitions.find(c=>c.format==='Liga');return `${heading('BEM-VINDO À MES','THE FUTURE OF MAMOBALL','Mamoball European Series · A futura casa comum das ligas europeias.',(state.permissions.admin?btn('Registar equipa','register-team','primary','plus'):''))}<section class="hero"><div class="hero-copy"><span class="tag">TODAS AS LIGAS · UMA SÓ CASA</span><h2>O MAMOBALL EUROPEU.<br>UMA <span>HISTÓRIA COMUM.</span></h2><p>Ligas, clubes e jogadores num só lugar.<br>Resultados de hoje. Memórias para sempre.</p>${btn('Explorar competições','explore','primary','arrow')}<button class="btn ghost" data-nav="newcomers" style="margin-top:12px">Sou novo · Começar aqui</button></div><div class="hero-art">${pitch}<span class="art-label">THE FUTURE OF MAMOBALL</span></div></section><div class="stats">${[[state.competitions.length,'Competições','trophy'],[state.teams.length,'Equipas registadas','shield'],[state.players.length,'Jogadores registados','teams'],[state.matches.filter(m=>m.home_score!==null).length,'Jogos concluídos','ball']].map(([n,t,i])=>`<div class="stat"><div class="stat-top">${t}${icon(i)}</div><div class="stat-value">${n}</div></div>`).join('')}</div>${!state.competitions.length&&state.permissions.admin?`<div class="notice">A tua liga real começa do zero. Completa o perfil e cria a primeira competição na Administração. <button class="link lime" data-nav="setup">Ver configuração →</button></div>`:''}<div class="columns"><section><div class="section-head"><h2>Em competição</h2><button class="link" data-nav="competitions">Ver todas ${icon('arrow')}</button></div><div class="comp-list">${state.competitions.slice(0,3).map(compRow).join('')||empty('O PRIMEIRO APITO ESTÁ A CHEGAR.','As novas competições vão aparecer aqui.')}</div></section><section><div class="section-head"><h2>Próximos jogos</h2><button class="link" data-nav="calendar">Calendário ${icon('arrow')}</button></div>${upcoming.length?`<div class="panel">${upcoming.map(m=>matchCard(m)).join('')}</div>`:empty('EM PREPARAÇÃO','Os jogos aparecem quando a organização iniciar uma competição.','calendar')}</section></div><div class="columns lower"><section><div class="section-head"><h2>A corrida pelo topo</h2></div>${first?tableView(state.tables[first.id]||[]):empty('CADA PONTO CONTA.','A classificação será calculada a partir dos resultados oficiais.')}</section><section><div class="section-head"><h2>Mais do que um jogo</h2></div><div class="community"><span style="color:#b8a6fb">${icon('discord')}</span><h3>A TUA LIGA, SEMPRE CONTIGO.</h3><p>Resultados, inscrições e o teu perfil.<br>Website e Discord, no mesmo campo.</p>${btn('Abrir Discord Hub','discord','purple','arrow')}</div></section></div>`}
function tableView(rows){if(!rows.length)return empty('A CLASSIFICAÇÃO COMEÇA AQUI.','Inscreve as equipas e inicia a competição.');return `<div class="panel table-wrap"><table><thead><tr><th>#</th><th>EQUIPA</th><th>J</th><th>V</th><th>E</th><th>D</th><th>DG</th><th>PTS</th><th>FORMA</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td class="pos">${i+1}</td><td><div class="team-cell">${shield(team(r.id))}${esc(team(r.id)?.name)}</div></td><td>${r.played}</td><td>${r.wins}</td><td>${r.draws}</td><td>${r.losses}</td><td>${r.gd}</td><td class="points">${r.points}</td><td><div class="form-dots">${r.form.map(x=>`<span class="${x==='D'?'loss':x==='E'?'draw':''}">${x}</span>`).join('')}</div></td></tr>`).join('')}</tbody></table></div>`}
function competitionsView(){const cs=state.competitions.filter(c=>filter==='Todas'||c.format===filter);return `${heading('ESCOLHE O TEU PALCO','COMPETIÇÕES','Vários formatos. A mesma vontade de ganhar.',state.permissions.admin?btn('Nova competição','new-competition','primary','plus'):'')}<div class="filters">${['Todas','Liga','Eliminação direta','Grupos + playoffs','Sistema suíço'].map(x=>`<button class="filter ${filter===x?'active':''}" data-filter="${x}">${x}</button>`).join('')}</div><div class="grid3">${cs.map(c=>`<article class="panel comp-card"><div class="card-top"><span class="competition-symbol ${c.color}">${icon('trophy')}</span>${badge(c.status,c.color)}</div><h3>${esc(c.name)}</h3><p class="muted small">${esc(c.season)}</p><div class="card-foot"><span>${esc(c.mode)} · ${esc(c.format)}</span><button class="link lime" data-comp="${c.id}">Explorar ${icon('arrow')}</button></div></article>`).join('')}</div>${!cs.length?empty('O PALCO ESTÁ PRONTO.','Ainda não existem competições neste formato.'):''}`}
function competitionView(){const c=state.competitions.find(c=>c.id===compId);if(!c)return competitionsView();const entries=state.entries.filter(e=>e.competition_id===c.id),matches=state.matches.filter(m=>m.competition_id===c.id);const tabs=c.format==='Eliminação direta'?['Bracket','Jogos','Equipas','Regras']:c.format==='Grupos + playoffs'?['Grupos','Playoffs','Jogos','Equipas','Regras']:['Classificação','Jogos','Equipas','Regras'];if(!tabs.includes(detailTab))detailTab='Jogos';return `<button class="link" data-nav="competitions" style="margin-bottom:20px">← Todas as competições</button>${heading(esc(c.season)+' · '+esc(c.mode),esc(c.name),esc(c.format)+' · '+entries.length+'/'+c.teams+' equipas',c.rawStatus==='open'&&state.permissions.admin?btn('Inscrever equipa','enroll','primary','plus'):badge(c.status,c.color))}${state.permissions.admin?`<div class="filters">${c.rawStatus==='open'?btn('Gerar jogos e iniciar','start:'+c.id,'ghost','bolt'):c.rawStatus==='active'?`${c.format!=='Liga'?btn('Gerar próxima fase','advance:'+c.id,'ghost','arrow'):''}${btn('Encerrar competição','finish:'+c.id,'ghost','trophy')}`:''}</div>`:''}<div class="tabs">${tabs.map(t=>`<button class="${detailTab===t?'active':''}" data-tab="${t}">${t}</button>`).join('')}</div>${detailTab==='Bracket'||detailTab==='Playoffs'?bracketLive(matches):['Classificação','Grupos'].includes(detailTab)?(c.format==='Grupos + playoffs'?`<div class="grid2">${[...new Set(entries.map(e=>e.group_name))].filter(Boolean).sort().map(g=>`<section><h3 style="margin-bottom:15px">Grupo ${esc(g)}</h3>${tableView((state.tables[c.id]||[]).filter(r=>entries.some(e=>e.team_id===r.id&&e.group_name===g)))}</section>`).join('')||empty('GRUPOS POR DEFINIR','Os grupos serão criados ao iniciar a competição.')}</div>`:tableView(state.tables[c.id]||[])):detailTab==='Equipas'?`<div class="grid3">${entries.map(e=>teamCard(team(e.team_id))).join('')}</div>${!entries.length?empty('INSCRIÇÕES ABERTAS','As equipas inscritas aparecem aqui.'):''}`:detailTab==='Regras'?`<div class="panel section-pad"><h3>Regras do formato</h3><p class="muted" style="line-height:2">${c.format==='Liga'?'Todos contra todos, uma volta. Vitória: 3 pontos; empate: 1; derrota: 0.':c.format==='Sistema suíço'?'Número par de equipas. Rondas: arredondamento por excesso de log₂ do número de equipas. Emparelhamentos por classificação, sem repetir adversários. Vitória: 3 pontos; empate: 1.':c.format==='Grupos + playoffs'?'Grupos de 4 equipas, uma volta. As duas primeiras de cada grupo avançam para eliminatórias cruzadas. Exige 8, 16 ou 32 equipas.':'Eliminação direta com 4, 8, 16 ou 32 equipas. Empate exige vencedor explícito do desempate.'}<br>Desempate da classificação: ${c.format==='Sistema suíço'?'pontos, Buchholz, diferença de golos, golos marcados, ID de registo.':'pontos, diferença de golos, golos marcados, ID de registo.'}<br>Ordem inicial: ordem de inscrição. A organização confirma os resultados.<br>Resultados de uma fase ficam bloqueados quando geram a fase seguinte.</p></div>`:matches.length?`<div class="grid2">${[...new Set(matches.map(m=>m.stage+':'+m.round))].map(key=>{const ms=matches.filter(m=>m.stage+':'+m.round===key);return `<section><h3 style="margin-bottom:14px">${({league:'Jornada',groups:'Grupos · Jornada',knockout:'Eliminatórias · Ronda',swiss:'Suíço · Ronda'})[ms[0].stage]} ${ms[0].round}</h3><div class="panel">${ms.map(m=>matchCard(m,state.permissions.admin)).join('')}</div></section>`}).join('')}</div>`:empty('À ESPERA DO PRIMEIRO APITO','Os jogos são gerados pela organização depois das inscrições.')}`}
function calendarView(){const ms=state.matches.filter(m=>calendarFilter==='Todos'||(calendarFilter==='Próximos'?m.home_score===null:m.home_score!==null)).sort((a,b)=>(a.scheduled||'9999').localeCompare(b.scheduled||'9999'));return `${heading('NÃO PERDAS UM MINUTO','CALENDÁRIO','Horários apresentados em Europe/Lisbon.')}<div class="filters">${['Todos','Próximos','Resultados'].map(x=>`<button class="filter ${calendarFilter===x?'active':''}" data-calendar="${x}">${x}</button>`).join('')}</div>${ms.length?`<div class="grid2">${ms.map(m=>`<div class="panel">${matchCard(m,state.permissions.admin)}</div>`).join('')}</div>`:empty('AINDA SEM JOGOS','O calendário será preenchido ao iniciar as competições.','calendar')}`}
function playersView(){return `${heading('A COMUNIDADE EM CAMPO','JOGADORES','Os jogadores oficiais da liga.',state.permissions.admin?btn('Registar jogador','register-player','primary','plus'):'')}<div class="filters"><input class="search-field" id="player-search" placeholder="Pesquisar nick ou ID Mamoball..." aria-label="Pesquisar jogador" value="${esc(playerQuery)}"></div><div class="panel table-wrap"><table><thead><tr><th>JOGADOR</th><th>EQUIPA</th><th>POSIÇÃO</th><th></th></tr></thead><tbody id="player-results">${playerResults()}</tbody></table></div>`}
function playerResults(){return state.players.filter(p=>(p.nick+' '+p.mamo).toLowerCase().includes(playerQuery.toLowerCase())).map(p=>`<tr><td><div class="team-cell"><span class="player-avatar">${avatarHtml(p.avatar,p.nick.slice(0,2).toUpperCase())}</span><span>${esc(p.nick)}<small class="muted" style="display:block;margin-top:4px;font-size:9px">${esc(p.mamo)}</small></span></div></td><td><div class="team-cell">${shield(team(p.team))}${esc(team(p.team)?.name||'Sem equipa')}</div></td><td class="muted">${esc(p.position)}</td><td><button class="link" data-link-player="${p.id}">Este jogador sou eu ${icon('link')}</button></td></tr>`).join('')||'<tr><td colspan="4" class="muted">Nenhum jogador encontrado.</td></tr>'}
function hallView(){if(!state.awards.length)return `${heading('A HISTÓRIA ESCREVE-SE AQUI','HALL OF FAME','Os troféus passam. O legado fica.')}<section class="hall-hero"><div>${icon('trophy')}<div class="eyebrow" style="color:#c8bb80;margin-top:20px">O PRIMEIRO CAPÍTULO</div><h2>AS LENDAS AINDA<br>ESTÃO POR ESCREVER.</h2><p>Os campeões serão registados automaticamente<br>quando a organização encerrar cada competição.</p></div></section><div class="grid3 lower">${['Campeões','Jogador da época','Bota de ouro'].map(t=>`<div class="panel award">${icon('star')}<h3>${t}</h3><div class="placeholder">A DEFINIR</div></div>`).join('')}</div>`;return `${heading('A HISTÓRIA ESCREVE-SE AQUI','HALL OF FAME','Conquistas oficiais, preservadas por competição e época.')}<div class="grid3">${state.awards.map(a=>{const c=state.competitions.find(c=>c.id===a.competition_id);return `<div class="panel award">${icon(a.type==='Campeão'?'trophy':'star')}<div class="eyebrow">${esc(c?.season)}</div><h3>${esc(a.type)}</h3><h2 style="margin:20px 0;color:var(--lime)">${esc(a.team_id?team(a.team_id)?.name:state.players.find(p=>p.id===a.player_id)?.nick)}</h2><p>${esc(c?.name)}</p></div>`}).join('')}</div>`}
function adminView(){if(!state.permissions.admin)return empty('ACESSO RESERVADO','Esta área é exclusiva da organização.');const pending=state.requests.filter(r=>r.status==='Pendente');return `${heading('CENTRO DE OPERAÇÕES','ADMINISTRAÇÃO','Gestão da liga com permissões verificadas no servidor.',btn('Nova competição','new-competition','primary','plus'))}<div class="filters">${btn('Registar jogador','register-player','ghost','player')}${btn('Atribuir prémio','award','ghost','star')}${btn('Exportar dados','export-data','ghost','download')}<button class="btn ghost" data-nav="setup">Configuração</button></div><div class="grid2"><div class="panel section-pad"><div class="section-head"><h3 style="margin:0">Pedidos de associação</h3>${badge(pending.length+' pendentes','orange')}</div>${pending.map(r=>`<div class="list-item"><div><strong>${esc(r.nick)}</strong><p>Jogador: ${esc(state.players.find(p=>p.id===r.player)?.nick)}</p></div><div class="row-actions">${btn('Aprovar','approve:'+r.id,'primary small')}${btn('Recusar','reject:'+r.id,'small')}</div></div>`).join('')||'<p class="muted small">Não há pedidos pendentes.</p>'}</div><div class="panel section-pad"><div class="section-head"><h3 style="margin:0">Pedidos de alteração de ID</h3>${badge((state.idRequests||[]).length+' pendentes','orange')}</div>${(state.idRequests||[]).map(r=>`<div class="list-item"><div><strong>${esc(r.nick||r.discord_name||'Jogador')}</strong><p class="mono">${esc(r.old_mamo)} → ${esc(r.new_mamo)}</p></div><div class="row-actions">${btn('Aprovar','id-approve:'+r.id,'primary small')}${btn('Recusar','id-reject:'+r.id,'small')}</div></div>`).join('')||'<p class="muted small">Não há pedidos pendentes.</p>'}</div><div class="panel section-pad"><h3>Atividade partilhada</h3>${state.events.map(e=>`<div class="list-item"><p style="margin:0">${esc(e.text)}</p><span class="small muted">${e.time}</span></div>`).join('')||'<p class="muted small">As alterações na liga vão aparecer aqui.</p>'}</div></div><div class="section-head lower"><h2>Competições</h2></div><div class="comp-list">${state.competitions.map(compRow).join('')||'<p class="muted">Cria a primeira competição para começar.</p>'}</div>`}
function studioView(){if(state.teams.length<2)return `${heading('A IDENTIDADE DA TUA LIGA','DESIGN STUDIO','Designs automáticos para cada momento.')}${empty('DÁ COR À TUA LIGA.','Regista pelo menos duas equipas para criar os primeiros designs.','studio')}`;const s=state.studio;return `${heading('A IDENTIDADE DA TUA LIGA','DESIGN STUDIO','Resultados e equipas reais. Exportação em SVG e PNG.',btn('Exportar PNG','export-png','primary','download'))}<div class="grid2"><div class="panel studio-preview" id="design-preview"></div><div class="panel studio-controls"><h3 style="margin-bottom:23px">O teu próximo anúncio</h3><div class="field"><label for="design-match">Preencher a partir de um jogo</label><select id="design-match"><option value="">Selecionar jogo…</option>${state.matches.map(m=>`<option value="${m.id}">#${m.id} ${esc(team(m.home_id)?.name)} × ${esc(team(m.away_id)?.name)}</option>`).join('')}</select></div><div class="field"><label for="design-type">Tipo de design</label><select id="design-type" data-studio="type">${['Resultado','Próximo jogo','Contratação'].map(t=>`<option ${s.type===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="form-grid">${['home','away'].map((k,i)=>`<div class="field"><label for="design-${k}">${i?'Adversário':'Equipa principal'}</label><select id="design-${k}" data-studio="${k}">${state.teams.map(t=>`<option value="${t.id}" ${Number(s[k])===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></div>`).join('')}</div><div class="field"><label for="design-score">${s.type==='Resultado'?'Resultado':s.type==='Contratação'?'Nome do jogador':'Data e hora'}</label><input id="design-score" data-studio="score" value="${esc(s.score)}" maxlength="30"></div><div class="field"><label for="design-color">Cor de destaque</label><select id="design-color" data-studio="accent">${[['#c2f970','MES Lime'],['#b6a5f7','Nebula Purple'],['#82cddd','Arctic Blue'],['#edb87f','Solar Orange']].map(([v,t])=>`<option value="${v}" ${s.accent===v?'selected':''}>${t}</option>`).join('')}</select></div>${btn('Exportar SVG','export-design','ghost','download')}<p class="muted small" style="line-height:1.9;margin-top:15px">1080 × 1080 px. O texto livre do design não altera os resultados oficiais.</p></div></div>`}
function modal(title,content){document.getElementById('overlay').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-header"><h2>${title}</h2><button class="icon-btn" data-action="close" aria-label="Fechar">${icon('close')}</button></div>${content}</section></div>`;setTimeout(()=>document.querySelector('.modal input,.modal select,.modal button')?.focus(),0)}
function closeModal(){document.getElementById('overlay').innerHTML=''}
function linkPlayer(id){if(!state.permissions.authenticated){nav('login');return}if(!state.players.length){toast('Ainda não existem jogadores registados.');return}modal('Associar jogador',`<p>A organização terá de aprovar esta ligação.</p><form id="link-form"><div class="field"><label for="f-player">Jogador</label><select id="f-player" name="player">${state.players.map(p=>`<option value="${p.id}" ${Number(id)===p.id?'selected':''}>${esc(p.nick)} · ${esc(team(p.team)?.name||'Sem equipa')}</option>`).join('')}</select></div><button class="btn primary" type="submit">Enviar pedido</button></form>`)}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)}
async function action(a){try{if(['register-team','enroll'].includes(a)&&!state.permissions.admin){toast('O registo e as inscrições de equipas são geridos pela administração.');return;}if(a==='oauth-info'){modal('Login Discord em preparação',`<p>O fluxo de login já está implementado. Falta configurar a aplicação Discord para permitir a autorização.</p>${state.permissions.admin?'<button class="btn primary" data-nav="setup">Abrir configuração</button>':'<p>A organização vai disponibilizar o login quando terminar a configuração.</p>'}`);return}if(a==='logout'){const r=await fetch('/api/auth/logout',{method:'POST',headers:{'X-Nexus-Request':'1'}});if(!r.ok)throw new Error('Não foi possível terminar a sessão.');page='login';await refresh();toast('Sessão Discord terminada.');return}if(a==='copy-callback'){await navigator.clipboard.writeText(state.config.oauth.redirectUri);toast('URL de retorno copiado.');return}if(['register-team','link-player','enroll'].includes(a)&&!state.permissions.authenticated){nav('login');return}if(a==='menu'){document.querySelector('.sidebar').classList.toggle('open');return}if(a==='close'){closeModal();return}if(a==='explore'){nav('competitions');return}if(a==='discord'){nav('discord');return}if(a==='register-profile'){nav('profile');return}if(a==='link-player'){linkPlayer();return}if(a==='link-code'){const r=await api('link.create');modal('Confirmar no Discord',`<p>${esc(r.message)}</p><div class="pitch-note" style="word-break:break-all;color:var(--lime)">/ligar codigo:${esc(r.code)}</div><p style="margin-top:18px">Não partilhes este código. Depois de o usares no Discord, atualiza o perfil.</p>${btn('Atualizar perfil','refresh','primary')}`);return}if(a==='refresh'){closeModal();await refresh();return}if(a==='register-team'){modal('A tua equipa começa aqui',`<form id="team-form">${field('Nome da equipa','name','',35)}${field('Abreviatura','tag','',3)}<div class="form-grid"><div class="field"><label for="f-region">Região</label><select id="f-region" name="region"><option>Portugal</option><option>Brasil</option><option>Internacional</option></select></div><div class="field"><label for="f-color">Cor</label><input id="f-color" name="color" type="color" value="#c2f970"></div></div><p>Registo reservado à administração. A equipa fica sob a tua gestão.</p><button class="btn primary" type="submit">Registar equipa</button></form>`);return}if(a==='register-player'){modal('Registar jogador',`<form id="player-form">${field('Nick do jogador','nick','',24)}${field('ID Mamoball (6 caracteres)','mamo','',6)}<div class="field"><label for="f-team">Equipa</label><select id="f-team" name="team"><option value="0">Sem equipa</option>${state.teams.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select></div><div class="field"><label for="f-position">Posição</label><select id="f-position" name="position"><option>Avançado</option><option>Médio</option><option>Defesa</option><option>Guarda-redes</option></select></div><button class="btn primary" type="submit">Registar jogador</button></form>`);return}if(a==='new-competition'){modal('Criar competição',`<form id="competition-form">${field('Nome','name','',45)}${field('Época','season','Época 01',40)}<div class="form-grid"><div class="field"><label for="f-format">Formato</label><select id="f-format" name="format"><option>Liga</option><option>Eliminação direta</option><option>Grupos + playoffs</option><option>Sistema suíço</option></select></div><div class="field"><label for="f-mode">Modo</label><select id="f-mode" name="mode"><option>4v4</option><option>3v3</option><option>2v2</option><option>1v1</option></select></div></div><div class="field"><label for="f-teams">Lugares</label><select id="f-teams" name="teams"><option>8</option><option>16</option><option>32</option><option>4</option></select></div><button class="btn primary" type="submit">Criar competição</button></form>`);return}if(a==='enroll'){const teams=state.teams.filter(t=>state.permissions.admin||t.owner_id===state.profile.id);if(!teams.length){toast('Regista primeiro uma equipa da qual sejas capitão.');return}modal('Inscrever equipa',`<form id="enroll-form"><div class="field"><label for="f-team">Equipa</label><select id="f-team" name="team">${teams.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select></div><button class="btn primary" type="submit">Confirmar inscrição</button></form>`);return}if(a==='activity'){modal('Atividade da liga',state.events.map(e=>`<div class="list-item"><p>${esc(e.text)}</p><span class="muted small">${e.time}</span></div>`).join('')||'<p>A atividade detalhada está disponível à organização.</p>');return}if(a==='customize'){customizeModal();return}if(a.startsWith('media-remove:')){await mutate('media.remove',{kind:a.split(':')[1]},'profile');return}if(a==='id-change'){modal('Pedir alteração de ID',`<form id="mamo-request-form"><p class="muted small" style="line-height:1.8;margin-bottom:16px">ID atual: <b class="mono">${esc(state.profile.mamo)}</b>. A administração analisa o pedido. Depois de enviares, só podes fazer outro pedido dentro de 24 horas.</p><div class="field"><label for="f-newmamo">Novo ID Mamoball</label><input id="f-newmamo" name="mamo" required minlength="6" maxlength="6" pattern="[A-Za-z0-9]{6}" autocomplete="off" spellcheck="false" class="mono-input" placeholder="Ex.: A1B2C3"></div><p class="muted small" style="line-height:1.8;margin-bottom:18px">Se precisares de ajuda, abre um ticket no Discord e fala com a administração.</p><div class="row-actions"><button class="btn primary" type="submit">Enviar pedido</button>${ticketButton()}</div></form>`);return}if(a.startsWith('id-approve:')||a.startsWith('id-reject:')){await mutate('mamo.review',{id:a.split(':')[1],status:a.startsWith('id-approve:')?'Aprovado':'Recusado'});return}if(a.startsWith('media-clear:')){const [,kind,user]=a.split(':');await mutate('media.remove',{kind,user});return}if(a.startsWith('approve:')||a.startsWith('reject:')){await mutate('request.review',{id:a.split(':')[1],status:a.startsWith('approve:')?'Aprovado':'Recusado'});return}if(/^(start|advance|finish):/.test(a)){const [op,id]=a.split(':');modal('Confirmar alteração',`<p>${op==='start'?'As inscrições serão fechadas e os jogos serão gerados por ordem de inscrição.':op==='advance'?'Os resultados da fase anterior ficarão bloqueados ao gerar a fase seguinte.':'A competição será encerrada e o campeão adicionado ao Hall of Fame. Os resultados ficam bloqueados.'}</p><div class="form-actions">${btn('Cancelar','close','ghost')}${btn('Confirmar','confirmed:'+op+':'+id,'primary')}</div>`);return}if(a.startsWith('confirmed:')){const [,op,id]=a.split(':');await mutate('competition.'+op,{id});return}if(a==='award'){const cs=state.competitions.filter(c=>c.rawStatus==='finished');if(!cs.length||!state.players.length){toast('É necessária uma competição encerrada e jogadores registados.');return}modal('Atribuir prémio',`<form id="award-form"><div class="field"><label>Competição</label><select name="competition">${cs.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Prémio</label><select name="type"><option>MVP</option><option>Bota de ouro</option></select></div><div class="field"><label>Jogador</label><select name="player">${state.players.map(p=>`<option value="${p.id}">${esc(p.nick)}</option>`).join('')}</select></div><button type="submit" class="btn primary">Guardar prémio</button></form>`);return}if(a==='download-config'){const r=await api('setup.bot-config');download(new Blob([r.content],{type:'text/plain'}),'nexus-bot.env');toast('Configuração privada descarregada. Renomeia para .env na pasta do bot.');return}if(a==='export-data'){const r=await api('export');download(new Blob([JSON.stringify(r,null,2)],{type:'application/json'}),'nexus-export-'+new Date().toISOString().slice(0,10)+'.json');return}if(a==='export-design'){download(new Blob([designSVG()],{type:'image/svg+xml'}),'nexus-design.svg');return}if(a==='export-png'){const image=new Image(),url=URL.createObjectURL(new Blob([designSVG()],{type:'image/svg+xml'}));image.onload=()=>{const canvas=document.createElement('canvas');canvas.width=1080;canvas.height=1080;canvas.getContext('2d').drawImage(image,0,0);canvas.toBlob(blob=>{if(blob)download(blob,'nexus-design.png');URL.revokeObjectURL(url)},'image/png')};image.onerror=()=>{URL.revokeObjectURL(url);toast('Não foi possível exportar PNG. Usa SVG.')};image.src=url;return}}catch(e){toast(e.message)}}
function matchModal(id){const m=state.matches.find(m=>m.id===Number(id));if(!m)return;const local=m.scheduled?new Date(new Date(m.scheduled).getTime()-new Date(m.scheduled).getTimezoneOffset()*60000).toISOString().slice(0,16):'';modal('Editar jogo #'+m.id,`<p>${esc(team(m.home_id)?.name)} × ${esc(team(m.away_id)?.name)}</p><form id="match-form"><input type="hidden" name="id" value="${m.id}"><input type="hidden" name="version" value="${m.version}"><div class="field"><label for="f-scheduled">Horário (${esc(Intl.DateTimeFormat().resolvedOptions().timeZone)})</label><input id="f-scheduled" name="scheduled" type="datetime-local" value="${local}"></div><div class="form-grid"><div class="field"><label>Golos da equipa da casa</label><input type="number" min="0" max="99" name="homeScore" value="${m.home_score??''}"></div><div class="field"><label>Golos do adversário</label><input type="number" min="0" max="99" name="awayScore" value="${m.away_score??''}"></div></div>${m.stage==='knockout'?`<div class="field"><label>Vencedor em caso de empate</label><select name="winner"><option value="">Selecionar…</option>${[m.home_id,m.away_id].map(id=>`<option value="${id}" ${m.winner_id===id?'selected':''}>${esc(team(id)?.name)}</option>`).join('')}</select></div>`:''}<p>Deixa ambos os golos vazios enquanto o jogo não estiver concluído.</p><button class="btn primary" type="submit">Guardar jogo</button></form>`)}
document.addEventListener('click',e=>{const el=e.target.closest('button,a');if(!el){if(e.target.classList.contains('modal-backdrop'))closeModal();return}if(el.dataset.nav){closeModal();nav(el.dataset.nav);return}if(el.getAttribute('href')==='#home'){e.preventDefault();nav('home');return}if(el.dataset.action){void action(el.dataset.action);return}if(el.dataset.comp){closeModal();compId=Number(el.dataset.comp);page='competition';detailTab='';render();window.scrollTo(0,0);return}if(el.dataset.filter){filter=el.dataset.filter;render();return}if(el.dataset.calendar){calendarFilter=el.dataset.calendar;render();return}if(el.dataset.tab){detailTab=el.dataset.tab;render();return}if(el.dataset.linkPlayer){linkPlayer(el.dataset.linkPlayer);return}if(el.dataset.match){matchModal(el.dataset.match);return}if(el.dataset.team){const t=team(el.dataset.team);modal(esc(t.name),`<div class="team-cell" style="margin-bottom:24px">${shield(t,true)}<div><h3>${esc(t.tag)} · ${esc(t.region)}</h3><p style="margin:7px 0 0">Capitão: ${esc(t.captain)}</p></div></div><h3 style="margin-bottom:15px">Plantel registado</h3>${state.players.filter(p=>p.team===t.id).map(p=>`<div class="list-item"><span>${esc(p.nick)}</span><span class="muted small">${esc(p.position)}</span></div>`).join('')||'<p>O plantel ainda não tem jogadores registados.</p>'}`)}});
document.addEventListener('input',e=>{if(e.target.id==='team-search'){teamQuery=e.target.value;document.getElementById('team-results').innerHTML=teamResults()}if(e.target.id==='player-search'){playerQuery=e.target.value;document.getElementById('player-results').innerHTML=playerResults()}if(e.target.dataset.studio&&e.target.tagName==='INPUT'){state.studio[e.target.dataset.studio]=e.target.value;drawStudio()}});
document.addEventListener('change',e=>{if(e.target.id==='design-match'){const m=state.matches.find(m=>m.id===Number(e.target.value));if(m){Object.assign(state.studio,{home:m.home_id,away:m.away_id,type:m.home_score===null?'Próximo jogo':'Resultado',score:m.home_score===null?(m.scheduled?new Date(m.scheduled).toLocaleString((window.MES_LOCALE||'pt-PT'),{timeZone:'Europe/Lisbon',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}):'A AGENDAR'):m.home_score+' : '+m.away_score});render()}return}if(!e.target.dataset.studio||e.target.tagName!=='SELECT')return;state.studio[e.target.dataset.studio]=e.target.value;if(e.target.dataset.studio==='type'){state.studio.score=e.target.value==='Resultado'?'0 : 0':e.target.value==='Contratação'?'NOVO JOGADOR':'A AGENDAR';render()}else drawStudio()});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,v=Object.fromEntries([...new FormData(f)].map(([k,val])=>[k,String(val).trim()]));if(f.id==='global-search'){const q=v.query.toLowerCase();modal('Resultados da pesquisa',state.teams.filter(t=>t.name.toLowerCase().includes(q)).map(t=>`<div class="result-line"><span>Equipa · ${esc(t.name)}</span><button data-team="${t.id}">Ver</button></div>`).join('')+state.competitions.filter(c=>c.name.toLowerCase().includes(q)).map(c=>`<div class="result-line"><span>Competição · ${esc(c.name)}</span><button data-comp="${c.id}">Ver</button></div>`).join('')+state.players.filter(p=>(p.nick+' '+p.mamo).toLowerCase().includes(q)).map(p=>`<div class="result-line"><span>Jogador · ${esc(p.nick)}</span><button data-link-player="${p.id}">Associar</button></div>`).join('')||'<p>Nenhum resultado encontrado.</p>');return}const map={'team-form':['team.create','teams'],'player-form':['player.create','players'],'profile-form':['profile.update','profile'],'mamo-form':['mamo.set','profile'],'mamo-request-form':['mamo.request','profile'],'style-form':['profile.style','profile'],'link-form':['request.create','profile'],'competition-form':['competition.create','competitions'],'enroll-form':['entry.create',null],'match-form':['match.update',null],'award-form':['award.create','hall']};if(!map[f.id])return;if(f.id==='enroll-form')v.competition=compId;if(f.id==='match-form'&&v.scheduled)v.scheduled=new Date(v.scheduled).toISOString();void mutate(map[f.id][0],v,map[f.id][1])});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();document.querySelector('.sidebar')?.classList.remove('open')}if(e.key==='Tab'&&document.querySelector('.modal')){const els=[...document.querySelectorAll('.modal button,.modal input:not([type=hidden]),.modal select')].filter(el=>!el.disabled);if(e.shiftKey&&document.activeElement===els[0]){e.preventDefault();els.at(-1)?.focus()}else if(!e.shiftKey&&document.activeElement===els.at(-1)){e.preventDefault();els[0]?.focus()}}});
function designSVG(){const s=state.studio,a=team(s.home),b=team(s.away),ac=s.accent;const title=s.type==='Resultado'?'FULL TIME':s.type==='Próximo jogo'?'MATCH DAY':'BEM-VINDO';const logo=(t,x)=>`<g transform="translate(${x} 407)"><path d="M-68-76H68V20L0 78-68 20Z" fill="${t.color}"/><text y="-5" text-anchor="middle" dominant-baseline="middle" font-family="Arial,sans-serif" font-size="39" font-weight="bold" fill="#142018">${esc(t.tag)}</text></g>`;return `<svg xmlns="http://www.w3.org/2000/svg" width="1080" height="1080" viewBox="0 0 1080 1080"><defs><radialGradient id="glow"><stop stop-color="${ac}" stop-opacity=".18"/><stop offset="1" stop-color="#121a12" stop-opacity="0"/></radialGradient><pattern id="grid" width="60" height="60" patternUnits="userSpaceOnUse"><path d="M60 0H0V60" fill="none" stroke="#ffffff" stroke-opacity=".045"/></pattern></defs><rect width="1080" height="1080" fill="#111811"/><rect width="1080" height="1080" fill="url(#grid)"/><ellipse cx="800" cy="400" rx="690" ry="720" fill="url(#glow)"/><path d="M720 0 350 1080M810 0 440 1080" stroke="${ac}" stroke-opacity=".12" stroke-width="2"/><rect x="68" y="70" width="6" height="39" fill="${ac}"/><text x="94" y="104" font-family="Arial,sans-serif" font-size="35" font-weight="bold" letter-spacing="7" fill="#eff7ea">MES</text><text x="1010" y="99" text-anchor="end" font-family="Arial,sans-serif" font-size="17" fill="#9fae99" letter-spacing="3">THE FUTURE OF MAMOBALL</text><text x="540" y="247" text-anchor="middle" font-family="Arial,sans-serif" font-size="92" font-weight="900" letter-spacing="-4" fill="${ac}">${title}</text>${s.type==='Contratação'?logo(a,540):logo(a,300)+logo(b,780)}${s.type==='Contratação'?'':`<text x="540" y="416" text-anchor="middle" font-family="Arial,sans-serif" font-size="35" fill="#74816e">VS</text>`}<text x="540" y="624" text-anchor="middle" font-family="Arial,sans-serif" font-size="${s.score.length>15?43:s.type==='Resultado'?118:70}" font-weight="bold" fill="#f4f8ef">${esc(s.score)}</text><text x="540" y="720" text-anchor="middle" font-family="Arial,sans-serif" font-size="${(a.name+b.name).length>29?24:30}" font-weight="bold" fill="#e0ead8">${esc(a.name.toUpperCase())}${s.type==='Contratação'?'':'  ×  '+esc(b.name.toUpperCase())}</text><text x="540" y="777" text-anchor="middle" font-family="Arial,sans-serif" font-size="18" letter-spacing="4" fill="#8c9b85">EUROPEAN SERIES · ${s.type==='Contratação'?'TRANSFER':'MAMOBALL'}</text><path d="M70 919H1010" stroke="#39452f"/><text x="70" y="973" font-family="Arial,sans-serif" font-size="16" letter-spacing="2" fill="#8c9b85">O JOGO É SÓ O INÍCIO.</text><text x="1010" y="973" text-anchor="end" font-family="Arial,sans-serif" font-size="14" fill="${ac}">MES / DESIGN STUDIO</text></svg>`}
function drawStudio(){const el=document.getElementById('design-preview');if(el&&team(state.studio.home)&&team(state.studio.away))el.innerHTML=designSVG()}

function bracketLive(matches){const ko=matches.filter(m=>m.stage==='knockout');if(!ko.length)return empty('BRACKET POR DEFINIR','As eliminatórias aparecem quando esta fase for gerada.');return `<div class="panel tournament">${[...new Set(ko.map(m=>m.round))].sort((a,b)=>a-b).map(r=>`<div class="bracket-round"><h3>RONDA ${r}</h3>${ko.filter(m=>m.round===r).map(m=>`<div class="bracket-match">${[[m.home_id,m.home_score],[m.away_id,m.away_score]].map(([id,score])=>`<div class="bracket-team"><span>${esc(team(id)?.name)}</span><b>${score??'—'}${m.winner_id===id?' ✓':''}</b></div>`).join('')}${state.permissions.admin?`<button class="link" data-match="${m.id}" style="padding:10px">Editar jogo →</button>`:''}</div>`).join('')}</div>`).join('')}</div>`}
const authMessages={join_blocked:'Não foi possível entrar no servidor Discord da MES. Se foste banido, contacta a organização.',join_failed:'Não foi possível adicionar-te ao servidor Discord da MES. Tenta novamente.',not_configured:'O login Discord ainda está a ser configurado pela organização.',invalid_state:'Esta tentativa de login expirou ou já foi utilizada. Tenta novamente.',account_changed:'A conta do website mudou durante o login. Tenta novamente.',cancelled:'Cancelaste a autorização. Podes continuar a explorar a liga.',invalid_code:'O código de autorização não é válido. Tenta novamente.',token_exchange_failed:'Não foi possível concluir a autorização Discord. Tenta novamente.',missing_scope:'Autoriza o acesso à identidade e à ligação ao servidor para continuar.',not_member:'Para entrar na liga, tens de pertencer ao servidor Discord da organização.',membership_pending:'Conclui a verificação de entrada no servidor Discord e tenta novamente.',discord_unavailable:'O Discord está temporariamente indisponível. Tenta novamente dentro de alguns instantes.',session_expired:'A sessão expirou. Entra novamente com Discord.',account_conflict:'Esta conta Discord já está ligada a outro perfil, ou o teu perfil já tem outra conta Discord. Contacta a organização; os dados não foram alterados.',too_many_attempts:'Fizeste várias tentativas. Aguarda um minuto antes de tentar novamente.',invalid_origin:'Abre o website pelo endereço oficial para entrar.',login_failed:'Não foi possível concluir o login. Tenta novamente.'};
let authNotice=typeof window.location!=='undefined'?new URLSearchParams(window.location.search).get('auth_error'):null;
function discordLoginButton(label='Continuar com Discord'){return state.config.oauth?.ready?`<a class="btn purple discord-login" href="/api/auth/discord" target="_top">${icon('discord')}${label}${icon('arrow')}</a>`:`<button class="btn purple discord-login" data-action="oauth-info">${icon('discord')}${label}${icon('arrow')}</button>`}
function loginView(){return `<div class="login-layout"><section class="login-story"><div class="eyebrow">A TUA IDENTIDADE NA LIGA</div><h1>UM JOGO.<br>UMA COMUNIDADE.<br><span>O TEU LUGAR.</span></h1><p>Entra com a tua conta Discord e começa a construir a tua história na MES.</p><div class="login-pitch">${pitch}</div><div class="login-features"><span>${icon('shield')}A tua equipa</span><span>${icon('trophy')}As tuas competições</span><span>${icon('player')}O teu perfil</span></div></section><section class="panel login-panel"><div class="login-icon">${icon('discord')}</div><span class="eyebrow">BEM-VINDO À MES</span><h2>ENTRA EM CAMPO.</h2><p>O teu perfil MES fica ligado à tua conta Discord.<br>Sem mais uma palavra-passe para decorar.</p>${authNotice?`<div class="notice" role="alert">${esc(authMessages[authNotice]||authMessages.login_failed)}</div>`:''}${discordLoginButton()}<div class="login-explanation"><span>${icon('check')}Criamos o teu perfil na primeira entrada.</span><span>${icon('check')}Depois defines o nick e o ID Mamoball.</span><span>${icon('check')}A associação a um jogador exige aprovação.</span></div>${!state.config.oauth?.ready?'<div class="login-pending"><span class="dot"></span>Login em preparação pela organização</div>':''}<p class="login-privacy">A autorização acontece no Discord. A MES não recebe a tua palavra-passe nem pede acesso às tuas mensagens. Discord OAuth2 não garante uma pessoa por conta; casos suspeitos exigem revisão administrativa.</p>${authNotice?btn('Limpar sessão','logout','ghost small'):''}<button class="link" data-nav="home">← Explorar a liga</button></section></div>`}
function profileView(){if(!state.permissions.authenticated)return loginView();const p=state.profile,linked=state.players.find(x=>x.id===p.player),oauth=state.auth?.method==='discord';return `${heading('A TUA IDENTIDADE NA LIGA','O MEU PERFIL','Define como apareces dentro e fora do campo.',oauth?btn('Terminar sessão','logout','ghost','logout'):'')}<div class="grid2"><div class="panel"><div ${bannerAttrs(p.banner)}><button class="btn small cover-edit" data-action="customize">${icon('edit')}Personalizar</button></div><div class="profile-body"><div class="profile-avatar">${avatarHtml(p.avatar,p.nick.slice(0,2).toUpperCase()||'TU')}</div><h2>${esc(p.nick||'Completa o teu perfil')}</h2><p class="muted small">${p.discordId?'@'+esc(p.discord):'Conta da organização'}</p><div style="margin:20px 0">${badge(linked?'Jogador associado':'Perfil da comunidade',linked?'':'purple')}</div><form id="profile-form">${field('Nick Mamoball','nick',p.nick,24)}<p class="muted small" style="margin-bottom:18px">O teu nick na liga. Não altera a tua conta dentro do Mamoball.</p><button class="btn primary" type="submit">${icon('check')}Guardar perfil</button></form></div></div><div><div class="panel section-pad"><div class="section-head"><h3 style="margin:0">Conta Discord</h3>${badge(oauth?'Sessão verificada':'Por autorizar',oauth?'':'orange')}</div>${oauth?`<div class="account-identity"><span class="bot-avatar">${icon('discord')}</span><div><strong>@${esc(p.discord)}</strong><small>${esc(p.discordId)}</small></div></div><p class="muted small" style="line-height:1.8;margin-top:18px">${state.permissions.member?'Ligação ao servidor da liga confirmada.':'O teu perfil está criado. As inscrições serão disponibilizadas quando a organização configurar o servidor da liga.'}</p>`:`<p class="muted small" style="line-height:1.9;margin-bottom:18px">Autoriza a tua conta diretamente no Discord para a associares a este perfil.</p>${discordLoginButton('Autorizar Discord')}`}<div class="profile-next"><span>01</span><div><strong>Completa o perfil</strong><p>Escolhe o nick e define o teu ID Mamoball.</p></div></div><div class="profile-next"><span>02</span><div><strong>Encontra o teu jogador</strong><p>Pede associação ao registo da competição.</p></div></div></div>${mamoPanel(p)}<div class="panel section-pad lower"><h3>O teu jogador na competição</h3>${linked?`<div class="team-cell">${shield(team(linked.team),true)}<div><h2>${esc(linked.nick)}</h2><p class="muted small" style="margin-top:7px">${esc(team(linked.team)?.name||'Sem equipa')}</p></div></div>`:`<p class="muted small" style="line-height:1.8;margin-bottom:18px">Se já estás registado num plantel, pede a ligação ao teu jogador. A organização confirma o pedido.</p>${btn('Pedir associação','link-player','ghost','link')}`}${state.requests.filter(r=>r.user===p.id).map(r=>`<div class="list-item"><span class="small">${esc(state.players.find(x=>x.id===r.player)?.nick||'Jogador')}</span>${badge(r.status,r.status==='Pendente'?'orange':'')}</div>`).join('')}</div></div></div>`}
function setupView(){const oauth=state.config.oauth||{ready:false,missing:[],redirectUri:''};return `${heading('PRIMEIRO O WEBSITE','CONFIGURAÇÃO','Prepara o login e a primeira época da tua liga.')}<div class="project-phases"><div class="phase current"><span>01</span><div><strong>Website</strong><small>Em desenvolvimento</small></div></div><div class="phase"><span>02</span><div><strong>Discord</strong><small>Próxima fase</small></div></div><div class="phase"><span>03</span><div><strong>Integração</strong><small>Depois de ambos prontos</small></div></div></div><div class="grid2"><div class="panel section-pad"><div class="section-head"><h3 style="margin:0">Login com Discord</h3>${badge(oauth.ready?'Configurado':'Credenciais por configurar',oauth.ready?'':'orange')}</div><p class="muted small" style="line-height:1.9;margin-bottom:20px">O login usa a tua aplicação Discord. Não é necessário instalar nem executar o bot nesta fase.</p>${[['Client ID',oauth.missing.includes('DISCORD_CLIENT_ID')?'Por configurar':'Configurado'],['Client Secret',oauth.missing.includes('DISCORD_CLIENT_SECRET')?'Por configurar':'Configurado'],['Proteção das sessões',oauth.missing.includes('OAUTH_ENCRYPTION_KEY')?'Por configurar':'Preparada'],['Servidor da liga',oauth.guildConfigured?'Definido':'Pode ser definido depois']].map(([a,b])=>`<div class="list-item"><span>${a}</span>${badge(b,b==='Configurado'||b==='Preparada'||b==='Definido'?'':'orange')}</div>`).join('')}<div class="callback-box"><label>URL de retorno OAuth2</label><code>${esc(oauth.redirectUri||'Por configurar')}</code>${oauth.redirectUri?btn('Copiar URL','copy-callback','ghost small'):''}</div><a class="btn purple" href="https://discord.com/developers/applications" target="_blank" rel="noopener noreferrer">Abrir Discord Developer Portal ↗</a></div><div class="panel section-pad"><h3>Ativar o login</h3><ol class="setup-list"><li>Cria uma aplicação Discord para a liga.</li><li>Em OAuth2, adiciona o URL de retorno apresentado aqui.</li><li>Configura o Client ID e o Client Secret no ambiente seguro do website.</li><li>Publica a configuração e testa “Continuar com Discord”.</li><li>Quando o servidor existir, define o seu ID para validar a pertença dos jogadores.</li></ol><p class="muted small" style="line-height:1.9">Scopes utilizados: <strong>identify</strong> e <strong>guilds.members.read</strong>. Não pedimos email, mensagens ou permissões de bot.</p><a class="btn ghost" href="/downloads/DISCORD-OAUTH-SETUP.md" download style="margin-top:20px">${icon('download')}Descarregar guia do login</a></div></div><div class="grid2 lower"><div class="panel section-pad"><h3>Começar a liga</h3><ol class="setup-list"><li>Completa o teu perfil.</li><li>Regista equipas e jogadores.</li><li>Cria competições e abre as inscrições.</li><li>Gera jogos, define horários e confirma resultados.</li><li>Encerra a época e arquiva os campeões.</li></ol></div><div class="panel section-pad"><h3>Acesso ao website</h3><p class="muted" style="line-height:1.9">O website pode ser alojado na Vercel. Os jogadores entram diretamente com Discord. No teu PC, o modo de teste local permite experimentar a administração antes de configurares o login.</p><p class="muted small" style="margin-top:16px;line-height:1.8">As permissões e as ações de gestão continuam a ser verificadas no servidor.</p><a class="btn ghost" href="/downloads/SETUP.md" download style="margin-top:22px">${icon('download')}Guia PC, GitHub e Vercel</a></div></div>`}
function discordView(){return `${heading('UMA COISA DE CADA VEZ','DISCORD · PRÓXIMA FASE','Agora estamos a construir o website.')}<div class="community" style="padding:35px"><span style="color:#b8a6fb">${icon('discord')}</span><h3>PRIMEIRO A CASA DA LIGA.</h3><p>O login Discord faz parte do website e pode funcionar sem o bot.<br>Depois de o website estar pronto, tratamos do servidor e do bot.<br>A ligação entre os dois será a última fase.</p><button class="btn purple" data-nav="profile">O meu perfil →</button></div>`}
refresh().then(()=>{if(typeof window.location!=='undefined'&&new URLSearchParams(window.location.search).get('auth')==='discord'){toast('Entraste com Discord. Completa o teu perfil.');window.history?.replaceState(null,'','#profile')}}).catch(async e=>{authNotice=e.authError||'login_failed';try{const r=await fetch('/api/auth/status');if(r.ok)state.config.oauth=await r.json()}catch{}page='login';render();toast(e.message)});
